// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint256 amount, address to) public {
        amount = bound(amount, 1, 1e24);
        vm.assume(to != address(0));
        vm.assume(to != address(c));

        vm.prank(address(this));
        c.supplyTokenTo(amount, to);

        // Rule: after a successful supply of `amount`, the beneficiary's credited
        // balance (imBalances) must equal the credits issued by the savings
        // contract, which the stub reports as exactly `amount`.
        assertTrue(c.imBalances(to) == amount);
    }
}

